// Kukicha Standard Library - ShellGuard (Subprocess Allowlist)
// Restricts which binaries and subcommands an agent can spawn, closing the
// remaining seam in the sandbox/netguard/shellguard triad. Pairs naturally
// with stdlib/shell — call shellguard.Check before shell.Output to gate
// the action through policy.
//
// Examples:
//
//	g := shellguard.New()
//	    |> shellguard.Allow("kubectl", list of string{"rollout", "get", "describe"})
//	    |> shellguard.Allow("git", list of string{"log", "diff", "status"})
//
//	shellguard.Check(g, "kubectl", "rollout", "restart", "api")
//	    onerr return error "policy: {error}"
//	shell.Check("kubectl", "rollout", "restart", "api") onerr return
