// Rule describes the permissions for one binary.
type Rule struct {
	subcommands   map[string]bool
	anySubcommand bool
	argValidator  func([]string) error
}

// Guard holds the per-binary rules. Construct via New and chain Allow /
// AllowAny / WithArgValidator to populate.
type Guard struct {
	rules map[string]Rule
}

// New creates an empty Guard. Until at least one Allow call, every Check
// call denies — fail-closed is the only safe default for subprocess spawn.
func New() Guard {
	return Guard{rules: map[string]Rule{}}
}

// Allow registers a binary with the given set of permitted subcommands.
// Multiple Allow calls for the same binary union their subcommand sets.
func Allow(g Guard, binary string, subcommands []string) Guard {
	rule, ok := g.rules[binary]
	if !ok {
		rule = Rule{subcommands: map[string]bool{}}
	}
	for _, sub := range subcommands {
		rule.subcommands[sub] = true
	}
	g.rules[binary] = rule
	return g
}

// AllowAny permits any subcommand for the given binary. Use sparingly — the
// whole point of shellguard is that subcommand is the meaningful unit.
func AllowAny(g Guard, binary string) Guard {
	rule, ok := g.rules[binary]
	if !ok {
		rule = Rule{subcommands: map[string]bool{}, anySubcommand: true}
	} else {
		rule.anySubcommand = true
	}
	g.rules[binary] = rule
	return g
}

// WithArgValidator attaches an optional predicate that runs after the
// subcommand check. The validator receives the full arg list (subcommand
// at index 0) and returns nil to allow or an error to deny.
func WithArgValidator(g Guard, binary string, validator func([]string) error) Guard {
	rule, ok := g.rules[binary]
	if !ok {
		rule = Rule{subcommands: map[string]bool{}, argValidator: validator}
	} else {
		rule.argValidator = validator
	}
	g.rules[binary] = rule
	return g
}

// AuthorizedCommand is an opaque authorization capability issued by Check.
// It binds the authorization to a specific binary and argument list;
// the fields are unexported so the authorization cannot be mutated or
// reused for a different invocation. Execution must go through the
// capability's Output() method — the guard enforces that the checked
// command is the one that runs.
type AuthorizedCommand struct {
	binary string
	args   []string
}

// Execute runs the authorized command through the shell builder, ensuring
// the same binary and args that passed Check are what actually executes.
func (cmd AuthorizedCommand) Output() (string, error) {
	return shell.Output(cmd.binary, cmd.args...)
}

// Check validates a planned invocation against the guard. If allowed,
// returns an opaque AuthorizedCommand capability bound to the exact
// binary and args; otherwise returns an error describing the policy
// violation. The capability must be executed through its Output() method
// so the authorization stays tied to the invocation.
//
// Global flags before the subcommand are recognized: the subcommand is
// the first argument that does not start with "-", so standard CLI
// shapes like `tofu -chdir=DIR plan` or `git -C DIR log` pass through
// the same allowlist. A flags-only invocation is rejected as missing a
// subcommand.
func Check(g Guard, name string, args ...string) (AuthorizedCommand, error) {
	rule, ok := g.rules[name]
	if !ok {
		return AuthorizedCommand{}, fmt.Errorf("shellguard: binary not in allowlist: %v", name)
	}
	if !rule.anySubcommand {
		subIdx := -1
		for i, arg := range args {
			if !kukistring.HasPrefix(arg, "-") {
				subIdx = i
				break
			}
		}
		if subIdx == -1 {
			return AuthorizedCommand{}, fmt.Errorf("shellguard: missing subcommand for %v", name)
		}
		sub := args[subIdx]
		if !rule.subcommands[sub] {
			return AuthorizedCommand{}, fmt.Errorf("shellguard: subcommand not allowed: %v %v", name, sub)
		}
	}
	if rule.argValidator != nil {
		err := rule.argValidator(args)
		if err != nil {
			return AuthorizedCommand{}, fmt.Errorf("shellguard: arg validation failed for %v: %v", name, err)
		}
	}
	return AuthorizedCommand{binary: name, args: args}, nil
}

// Allowed is the boolean form of Check: true only when Check would issue
// a capability. It discards the authorization — prefer Check + capability
// execution for any real invocation so the guard stays in the loop.
func Allowed(g Guard, name string, args ...string) bool {
	_, err := Check(g, name, args...)
	return err == nil
}

// IsAllowed is the English alias for Allowed — true only when Check would
// issue a capability. Reads as `if shellguard.IsAllowed(g, "git", "status")`.
func IsAllowed(g Guard, name string, args ...string) bool {
	_, err := Check(g, name, args...)
	return err == nil
}

// Run is an English alias for the AuthorizedCommand Output method.
// Reads as `cap |> shellguard.Run()`. Both spellings execute the
// authorized command via the shell builder.
func (cmd AuthorizedCommand) Run() (string, error) {
	return shell.Output(cmd.binary, cmd.args...)
}

// Lines runs the authorized command and returns its stdout split into
// lines, with the trailing empty element a final newline would produce
// dropped — shell.Lines parity through the capability.
// Example: entries := auth |> shellguard.Lines() onerr return
func (cmd AuthorizedCommand) Lines() ([]string, error) {
	return shell.Lines(cmd.binary, cmd.args...)
}

// Capture runs the authorized command and returns stdout and stderr
// separately — stream separation that was impossible through the
// capability before. Useful for logging stderr even on success.
// Example: out, errOut, err := auth |> shellguard.Capture() onerr return
func (cmd AuthorizedCommand) Capture() (string, string, error) {
	return shell.Capture(cmd.binary, cmd.args...)
}

// Preview renders the authorized command as a display string ("git log
// -n 5") without executing it. The binary and args are deliberately
// unexported, so this is the only way to audit-log what will run — use it
// before Output/Run/Lines/Capture.
// Example: log.Info("about to run: {auth |> shellguard.Preview()}")
func (cmd AuthorizedCommand) Preview() string {
	parts := []string{cmd.binary}
	parts = append(parts, cmd.args...)
	return kukistring.Join(parts, " ")
}
